for r in range(20, 27):
    for c in range(4, 7):
        if result_grid[r][c] == 1:
            result_grid[r-20][c] = 1

# Remove the bottom-right pattern (set back to 4s)
for r in range(20, 27):
    for c in range(4, 7):
        result_grid[r][c] = 4

print("Top-right pattern rows 0-6, cols 4-6:")
